let dragId=null;
function attachDrag(){document.querySelectorAll('[draggable=true]').forEach(el=>el.addEventListener('dragstart',e=>{dragId=el.dataset.id;e.dataTransfer.setData('text/plain',dragId);e.dataTransfer.effectAllowed='move'}));document.querySelectorAll('[data-drop-date]').forEach(el=>{el.addEventListener('dragover',e=>e.preventDefault());el.addEventListener('drop',async e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain')||dragId,original=eventById(id);if(!original?.start)return;const date=el.dataset.dropDate;let time=hm(original.start);if(el.classList.contains('day-col')){const offset=e.clientY-el.getBoundingClientRect().top,minute=Math.max(0,Math.min(1425,Math.round(offset/.75/15)*15));time=String(Math.floor(minute/60)).padStart(2,'0')+':'+String(minute%60).padStart(2,'0')}const next={...original,start:date+'T'+time+':00'},end=new Date(next.start);end.setMinutes(end.getMinutes()+(duration(original)||60));next.finish=day(end)+'T'+String(end.getHours()).padStart(2,'0')+':'+String(end.getMinutes()).padStart(2,'0')+':00';await proposeEvent(next)})})}
function timerSeconds(t=data.timer){let sum=(t?.segments||[]).reduce((s,a)=>s+Math.max(0,a.end-a.start),0);if(t?.state==='running')sum+=Math.max(0,Date.now()/1000-t.started);return sum}
function updateCalendarClock(date=new Date()){
 const clock=CalendarClock.position(date);
 document.querySelectorAll('[data-clock-day]').forEach(el=>{
  const current=el.dataset.clockDay===clock.day;el.classList.toggle('today',current);
  const dateButton=el.querySelector('.month-date');if(dateButton){if(current)dateButton.setAttribute('aria-current','date');else dateButton.removeAttribute('aria-current')}
 });
 document.querySelectorAll('[data-now-line]').forEach(el=>{
  el.hidden=el.dataset.nowLine!==clock.day||!clock.visible;el.style.top=clock.top+'px';
  el.querySelector('span').textContent=clock.time;el.setAttribute('aria-label','Hora actual en Madrid: '+clock.time);
 });
 document.querySelectorAll('[data-clock-event]').forEach(el=>{
  const event=eventById(el.dataset.clockEvent),current=!!event&&CalendarClock.active(event,clock);
  el.classList.toggle('is-current',current);if(current)el.setAttribute('aria-current','time');else el.removeAttribute('aria-current');
 });
 const dateLabel=$('[data-current-date]');if(dateLabel)dateLabel.textContent=dateFormatter(date,{weekday:'long',day:'numeric',month:'long'});
 return clock;
}
let lastClockDay=CalendarClock.now().day,clockRefreshPending=false;
function tick(){
 if(!data)return;
 document.querySelectorAll('.timer-value').forEach(el=>el.textContent=fmtTime(timerSeconds()));
 const clock=updateCalendarClock();
 if(clock.day!==lastClockDay&&!clockRefreshPending&&!$('#modal').children.length&&!document.activeElement?.matches('input,textarea,select')){
  clockRefreshPending=true;lastClockDay=clock.day;if(view==='today')anchor=clock.day;
  refresh().catch(e=>toast(e.message)).finally(()=>clockRefreshPending=false);
 }
}
window.timerUpdate=t=>{const old=data?.timer;if(!data)return;data.timer=t;if(old?.state!==t.state||old?.recovery!==t.recovery){render()}else tick()};
setInterval(tick,1000);
