function editDoubt(d=null,context=null){
 const task=context?.kind==='task'?context:taskFor(context);
 const extra=`<div class="form-grid">${select('Prioridad','priority',['alta','media','baja'],d?.priority||'media')}${select('Destinatario','recipient',['yo','profesor','chat'],d?.recipient||'yo')}${select('Tarea o ejercicio','task',[['','Sin tarea'],...tasks().map(t=>[t.id,t.title])],d?.task||task?.id||'',true)}${field('Archivo, página y apartado','reference',d?.reference||task?.references||'','text',true)}${area('Qué intenté','attempt',d?.attempt||'')}${area('Dónde me atasqué','stuck',d?.stuck||'')}</div>`;
 const answer=`<div class="form-grid">${select('Estado','status',doubtStates,d?.status||'abierta',true)}${area('Respuesta recibida','answer',d?.answer||'')}${field('Procedencia de la respuesta','provenance',d?.provenance||'','text',true)}${area('Comprobación / resolución','resolution',d?.resolution||'')}</div>`;
 showDialog(d?'Duda':'Nueva duda','',`<div class="form-grid">${select('Asignatura','subject',sidOptions(),d?.subject||context?.subject||selectedSubject,true)}${area('Pregunta','question',d?.question||'')}</div>${disclosure('doubt-extra','Intento y referencias',extra)}${disclosure('doubt-answer','Respuesta y comprobación',answer,!!d?.answer)}`,'doubt');
 dialogState={doubt:d||{},entity:context};
}
