async function proposeEvent(e){const result=await api('checkMove',e);dialogState={entity:e,alternative:result.alternative};if(!result.issues.length){showDialog('Confirmar sesión','Revisados disponibilidad, pausas, duración, dependencias y prueba vinculada.',`<p>${esc(e.title)}<br><b>${esc(dateFormatter(e.start,{weekday:'long',day:'numeric',month:'short'}))} · ${hm(e.start)}–${hm(e.finish)}</b></p><div class="dialog-footer">${button('closeModal','Cancelar')}${button('acceptEvent','Aplicar','','primary')}</div>`);dialogState={entity:e};return}showDialog('Revisar conflictos','No se ha cambiado el calendario.',`<div class="notice">${result.issues.map(esc).join('<br>')}</div>${result.alternative?`<div class="detail-block" style="margin-top:20px"><h3>Alternativa disponible</h3><p>${esc(dateFormatter(result.alternative.start,{weekday:'long',day:'numeric',month:'short'}))} · ${hm(result.alternative.start)}–${hm(result.alternative.finish)}</p>${button('acceptAlternative','Usar alternativa','','primary')}</div>`:'<p class="source-note" style="margin-top:16px">No se encontró un hueco compatible en los próximos 21 días. Reprograma manualmente o divide la sesión.</p>'}<div class="divider"></div><label class="field">Motivo de excepción voluntaria<input id="exceptionReason" placeholder="Escribe por qué aceptas este conflicto"></label><div class="dialog-footer">${button('closeModal','Volver')}${button('acceptException','Aceptar excepción')}</div>`);dialogState={entity:e,alternative:result.alternative}}
