document.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();b.closest('.more-menu')?.removeAttribute('open');try{await actions[b.dataset.act]?.(b)}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const old=$('.search-results');if(old)old.remove();if(query)$('#search').closest('.topbar').insertAdjacentHTML('beforeend',searchResults())}});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.dataset.filter){filters[el.dataset.filter]=el.checked;render();return}
 if(el.name==='mode'&&el.closest('[data-form=startTimer]')){$('#interval-options').hidden=el.value!=='intervalos';return}
 if(view==='focus'&&el.name==='subject'&&el.closest('[data-form=startTimer]')){const taskSelect=el.closest('form').querySelector('[name=task]');taskSelect.innerHTML=option([['','Estudio libre'],...tasks().filter(t=>t.subject===el.value).map(t=>[t.id,t.id+' · '+t.title])],'');return}
 if(el.dataset.change==='backupPath'){const path=$('#modal [name=path]');path.value=el.value;return}
 if(['includeUpcoming','acceptPartial'].includes(el.dataset.change))return;
 if(!el.dataset.change)return;const id=el.dataset.id,entity=eventById(id)||find(id),u=entity?.user||{};
 switch(el.dataset.change){
 case 'subjectFilter':subjectFilter=el.value;render();break;case 'statusFilter':statusFilter=el.value;render();break;case 'reviewSubject':selectedSubject=el.value;render();break;case 'doubtFilter':doubtFilter=el.value;render();break;
 case 'taskCheck':await api('saveUser',{id,user:{status:el.checked?'completada':'pendiente'}});await refresh();break;
 case 'detailStatus':await api('saveUser',{id,user:{[entity.category==='exam'?'assessment':'status']:el.value}});await refresh();break;
 case 'detailNotes':await api('saveUser',{id,user:{notes:el.value}});entity.user={...u,notes:el.value};toast('Notas guardadas');break;
 case 'grade':{const grade=el.value===''?null:Number(el.value);if(grade!==null&&(grade<0||grade>10))throw Error('Nota entre 0 y 10 o vacía');await api('saveUser',{id,user:{grade}});await refresh();break}
 case 'checkItem':{const checklist=structuredClone(u.checklist||[]);checklist[Number(el.dataset.index)].done=el.checked;await api('saveUser',{id,user:{checklist}});entity.user={...u,checklist};break}
 }
 }catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const values=Object.fromEntries(new FormData(form)),state=dialogState;try{
 switch(form.dataset.form){
 case 'replan':await previewReplanDialog(form,values,state);return;
 case 'startTimer':await api('startTimer',{...values,interval:values.mode==='intervalos'?Number(values.interval):0,rest:Number(values.rest)});await refresh();return;
 case 'event':{const old=state.entity;const e={...old,...values,date:null,start:null,finish:null,dateEnd:null};delete e.dateOnly;if(values.dateOnly){e.date=values.date;e.dateEnd=addDay(values.date,1)}else{if(!values.start)throw Error('Indica la hora de inicio o marca hora por confirmar');e.start=values.date+'T'+values.start+':00';if(values.finish)e.finish=values.date+'T'+values.finish+':00'}if(e.category==='study'||e.kind==='occurrence'){if(!e.finish)throw Error('Una sesión de estudio necesita hora de fin');await proposeEvent(e)}else{await storeEvent(e)}return}
 case 'entity':{const old=state.entity;const result=await api('saveEntity',{...old,...values,...(old.kind==='task'?{dependencies:(values.dependencies||'').split(',').map(x=>x.trim()).filter(Boolean)}:{})});selected=result.kind==='task'?result.id:null;if(result.kind==='subject'){selectedSubject=result.id;subjectOpen=true;subjectTab='tasks'};break}
 case 'doubt':await api('saveDoubt',{...state.doubt,...values,event:state.doubt.event||state.entity?.id||''});break;
 case 'time':{const d=new Date(values.date+'T'+values.time+':00');await api('saveTime',{...state.time,...values,seconds:Number(values.minutes)*60,date:d.toISOString()});break}
 case 'attempt':{const record={...values,task:state.task?.id||'',subject:state.entity.subject,event:state.entity.kind==='task'?'':state.entity.id,date:new Date().toISOString()};await api('saveAttempt',record);if(state.task)await api('saveUser',{id:state.task.id,user:{evidence:values.evidence}});break}
 case 'result':await api('saveUser',{id:state.entity.id,user:values});break;
 case 'checklist':await api('saveUser',{id:state.entity.id,user:{checklist:[...(state.entity.user?.checklist||[]),{text:values.text,done:false}]}});break;
 case 'review':if(!values.id)delete values.id;await api('saveReview',values);closeModal();await refresh();toast('Revisión guardada');return;
 case 'filePath':await api('fileByPath',{...state.payload,mode:state.fileMode,path:values.path});break;
 case 'previewFile':{const p=await api('previewFile',{path:values.path,type:state.fileType});importPreview(p);return}
 case 'grades':await saveGradeForm(form,state);return;
 case 'reminders':await api('reminders',{enabled:values.enabled==='true',minutes:Number(values.minutes)});break;
 case 'split':{const reserve=find(values.reserve);if(!reserve)throw Error('No hay una reserva posterior disponible');const minutes=Number(values.minutes);await api('splitSession',{id:state.entity.id,reserve:reserve.id,minutes,operation:values.operation});break}
 }
 closeModal();await refresh();toast('Guardado');
 }catch(err){toast(err.message)}});
