function fileDialog(type){showDialog(type==='xml'?'Abrir actualización XML':'Abrir calendario ICS','Elige el archivo con el selector de macOS o pega su ruta completa. Primero se valida; todavía no se modifica la base.',`${field('Ruta del archivo .'+type,'path','','text',true)}<div style="margin-top:15px">${button('browseFile','Seleccionar archivo…')}</div>`,'previewFile');dialogState={fileType:type};$('#modal button[type=submit]').textContent='Validar y revisar'}

function filePathDialog(mode,payload={}){const names={exportBackup:'Exportar copia SQLite',restoreBackup:'Restaurar copia SQLite',chooseMaterials:'Carpeta de materiales',saveText:'Guardar exportación'},folder=data.dataPath.replace(/universidad\.sqlite$/,''),ext=mode==='exportBackup'?'sqlite':(payload.title?.includes('Calendario')?'ics':payload.title?.includes('Plan')?'xml':'md'),path=mode==='chooseMaterials'?data.settings.materials:mode==='restoreBackup'?(data.backups[0]?folder+'Copias/'+data.backups[0]:''):'~/Desktop/Nodal-'+Date.now()+'.'+ext;showDialog(names[mode],mode==='restoreBackup'?'La restauración crea una copia del estado actual antes de reemplazarlo por el archivo elegido.':'Introduce una ruta completa o usa ~ para tu carpeta de usuario. Los archivos existentes no se sobrescriben.',`${mode==='restoreBackup'&&data.backups.length?`<label class="field">Copias locales<select data-change="backupPath">${option(data.backups.map(n=>[folder+'Copias/'+n,n]),path)}</select></label><div style="height:15px"></div>`:''}${field(mode==='chooseMaterials'?'Ruta de la carpeta':'Ruta del archivo','path',path,'text',true)}`,'filePath');dialogState={fileMode:mode,payload};$('#modal button[type=submit]').textContent=mode==='restoreBackup'?'Restaurar con copia previa':mode==='chooseMaterials'?'Usar esta carpeta':'Guardar archivo'}

actions.subjectsHome=()=>{subjectOpen=false;selected=null;render()};
actions.subjectTab=b=>{subjectTab=b.dataset.value;selected=null;render()};
actions.timeRecords=()=>{
 const list=data.times.slice().reverse().map(t=>`<article class="time-row"><div class="between"><b>${esc(t.subject)} · ${hours(t.seconds)}</b><span class="pill">${esc(t.mode)}</span></div><p class="small-text">${esc(t.label||t.task||'Estudio')}</p><div class="between"><small>${esc(dateFormatter(t.date,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',hour12:false}))}</small><div class="row">${button('editTime','Corregir',`data-id="${esc(t.id)}"`,'small quiet')}${button('deleteTime','Eliminar',`data-id="${esc(t.id)}"`,'small quiet')}</div></div></article>`).join('');
 showDialog('Registro de tiempo',`${hours(timeToday())} registradas hoy`,list||empty('Todavía no hay registros.','clock'));
 dialogState={kind:'timeRecords'};
};
actions.weeklyReview=()=>{
 const start=monday(anchor),review=data.reviews.find(r=>r.week===start)||{};
 showDialog('Revisión semanal',dateFormatter(start,{day:'numeric',month:'long'}),`<input type="hidden" name="id" value="${esc(review.id||'')}"><input type="hidden" name="week" value="${start}"><div class="stack">${area('Qué resolví sin ayuda','solo',review.solo)}${area('Qué requirió ayuda','help',review.help)}${area('Qué quedó sin hacer / por qué','pending',review.pending)}${area('Qué cambia la próxima semana','next',review.next)}</div>`,'review');
};
document.addEventListener('toggle',e=>{if(e.target.matches('details[data-disclosure]'))openSections.set(e.target.dataset.disclosure,e.target.open)},true);
document.addEventListener('click',e=>document.querySelectorAll('.more-menu[open]').forEach(menu=>{if(!menu.contains(e.target))menu.removeAttribute('open')}));
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});
